---@param go UnityEngine.GameObject @ 是否是3d对象类型 go为可选参数
function DreamSpaceSounds.Play( cue_, go_ )
    assert( type(cue_) == "table" )

    -- todo: 目前 单lua场景 运行时, 不播音效: (因为音效组件没有被启动)
    if DreamSpaceStates.IsSingleLuaScene() == true then 
        return
    end 

    if cue_.type == CueType.SFX then 
        CriWareUtils.PlaySe(cue_.sheetPath, cue_.cueName, go_ )
    elseif cue_.type == CueType.BGM then
        CriWareUtils.PlayMusic(cue_.sheetPath, cue_.cueName, go_ )
    end
end


---@param go UnityEngine.GameObject @ 是否是3d对象类型 go为可选参数
function DreamSpaceSounds.Stop( cue_, go_ )
    assert( type(cue_) == "table" )

    -- todo: 目前 单lua场景 运行时, 不播音效: (因为音效组件没有被启动)
    if DreamSpaceStates.IsSingleLuaScene() == true then 
        return
    end 

    if cue_.type == CueType.SFX then 
        CriWareUtils.Stop(cue_.sheetPath, cue_.cueName, go_ )
    elseif cue_.type == CueType.BGM then
        CriWareUtils.Stop(cue_.sheetPath, cue_.cueName, go_ )
    end
end



function DreamSpaceSounds.StopAll()
    CriWareUtils.StopAll()
end


return DreamSpaceSounds